const fs = require('fs');
const cachePath = '/data/cache_pendientes.json';
const productos = [];

for (const item of $input.all()) {
    const data = item.json;

    const rawCat = data['CATEGORÍA'] || '';
    const cat = rawCat ? rawCat.charAt(0).toUpperCase() + rawCat.slice(1).toLowerCase() : 'SinCategoria';
    const name = data['NOMBRE'] || '';

    const basePath = `/data/your-photos-folder/${cat}/${name}`;
    const extensions = ['.jpg', '.png', '.jpeg', '.JPG', '.PNG'];

    let imageBase64 = null;
    let finalPath = null;

    for (const ext of extensions) {
        if (fs.existsSync(basePath + ext)) {
            finalPath = basePath + ext;
            break;
        }
    }

    try {
        if (finalPath) {
            const ext = finalPath.split('.').pop().toLowerCase();
            const mime = (ext === 'png') ? 'image/png' : 'image/jpeg';
            const buffer = fs.readFileSync(finalPath);
            imageBase64 = `data:${mime};base64,${buffer.toString('base64')}`;
        }
    } catch (err) {
        console.error('Error leyendo imagen:', err.message);
    }

    const usd = data['PRECIO USD NUEVO'] ? `$${data['PRECIO USD NUEVO']} USD` : '';
    const cup = data['PRECIO CUP NUEVO'] ? `${data['PRECIO CUP NUEVO']} CUP` : '';
    const precioFinal = [cup, usd].filter(Boolean).join(' | ');

    productos.push({
        id_unico: data['CÓDIGO'],
        nombre: name,
        precio: precioFinal,
        estado: data['ESTADO PUBLICACIÓN'] || 'NO PUBLICADO',
        imagen: imageBase64
    });
}

fs.writeFileSync(cachePath, JSON.stringify(productos));

return [{ json: { status: 'success', total_cacheados: productos.length } }];

const fs = require('fs');
let productos = [];

try {
    const rawData = fs.readFileSync('/data/cache_pendientes.json', 'utf8');
    productos = JSON.parse(rawData);
} catch (e) {
    productos = [];
}

// Escapamos los datos para inyectarlos de forma 100% segura en JS
const safeProductosJson = JSON.stringify(productos).replace(/</g, '\\u003c');

let cardsHtml = '';
for (const prod of productos) {
    const imgSrc = prod.imagen ? prod.imagen : 'https://via.placeholder.com/400x400?text=Sin+Imagen';
    const colorBorde = prod.estado === 'PENDIENTE ACTUALIZAR' ? '#e74c3c' : '#6d1e68';

    // El botón AHORA SOLO RECIBE EL ID. Cero errores de sintaxis.
    cardsHtml += `
    <div class="card" id="card-${prod.id_unico}" style="border-left: 6px solid ${colorBorde};">
        <img src="${imgSrc}" loading="lazy" alt="Producto" />
        <div class="card-content">
            <h3>${prod.nombre}</h3>
            <p class="price">${prod.precio}</p>
            <p class="badge">${prod.estado}</p>
            <button onclick="prepararPublicacion('${prod.id_unico}')">
                Preparar y Publicar
            </button>
        </div>
    </div>`;
}

const html = `
<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Panel YourBrand</title>
    <style>
        body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background: #f4f4f9; padding: 20px; }
        .header { text-align: center; color: #6d1e68; margin-bottom: 30px; }
        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 20px; }
        .card { background: white; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }
        .card img { width: 100%; height: 250px; object-fit: cover; background: #eee; }
        .card-content { padding: 20px; }
        .card h3 { margin: 0 0 10px; font-size: 18px; color: #333; }
        .price { font-size: 22px; font-weight: bold; color: #ffb703; margin: 0 0 10px; }
        .badge { display: inline-block; padding: 4px 8px; background: #eee; border-radius: 4px; font-size: 12px; margin-bottom: 15px; font-weight: bold; }
        button { width: 100%; padding: 12px; background: #25D366; color: white; border: none; border-radius: 6px; font-size: 16px; font-weight: bold; cursor: pointer; }
    </style>
</head>
<body>
    <div class="header">
        <h1>Your Brand - Panel de Publicación</h1>
    </div>
    <div class="grid">
        ${cardsHtml || '<p style="text-align: center; grid-column: 1/-1; font-size: 18px;">Todo el inventario está publicado. ¡Excelente trabajo!</p>'}
    </div>

    <script>
    // La Base de Datos vive ahora en la memoria del navegador
    const DB_PRODUCTOS = ${safeProductosJson};

    async function marcarPublicado(id_unico) {
        document.getElementById('card-' + id_unico).style.display = 'none';
        try {
            await fetch('/webhook/api-publicar', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ id_unico: id_unico })
            });
        } catch(e) { console.error('Error sincronizando estado'); }
    }

    function prepararPublicacion(id_unico) {
        try {
            // Buscamos los datos limpios en la memoria
            const producto = DB_PRODUCTOS.find(p => String(p.id_unico) === String(id_unico));
            if (!producto) return alert('Error: Producto no encontrado en la base de datos local.');

            if (producto.imagen && producto.imagen.startsWith('data:image')) {
                const link = document.createElement('a');
                link.href = producto.imagen;
                // Limpiamos el nombre para evitar errores al guardar el archivo en el móvil
                const safeName = producto.nombre.replace(/[^a-z0-9]/gi, '_').toLowerCase();
                link.download = 'YourBrand_' + safeName + '.jpg';
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            }

            const texto = '🔥 *NUEVO INGRESO EN YOURBRAND OUTFIT* 🔥\\n\\n📦 Producto: ' + producto.nombre + '\\n💰 Precio: ' + producto.precio + '\\n\\n📍 ¡Visítanos o pide tu domicilio ahora!';

            marcarPublicado(id_unico);

            setTimeout(() => {
                window.location.href = 'whatsapp://send?text=' + encodeURIComponent(texto);
            }, 600);
        } catch(e) { 
            console.error(e);
            alert('Error preparando publicación.'); 
        }
    }
    </script>
</body>
</html>`;

return [{ json: { html: html } }];

